type El = WebdriverIO.Element;
const q = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

// ───────────────────────── системное окно сбоя / живо ли приложение ─────────────────────────

/** Закрыть системное окно (TestFlight «поделиться отзывом о сбое» и т.п.), если оно есть. true — окно было. */
export async function dismissCrashAlert(): Promise<boolean> {
  const has = await driver.getAlertText().then(() => true, () => false);
  if (!has) return false;
  await driver.execute('mobile: alert', { action: 'dismiss' }).catch(() => {});
  return true;
}
/** Приложение на переднем плане; если упало — закрыть окно сбоя, перезапустить и вернуть false. */
export async function aliveOrRelaunch(where: string): Promise<boolean> {
  const id = appId();
  if (!id) return true;
  if ((await driver.queryAppState(id)) === 4) return true;
  console.log(`[2110] ${where}: приложение не на переднем плане — окно сбоя закрыто, перезапуск`);
  await dismissCrashAlert();
  await driver.activateApp(id);
  await driver.pause(3000);
  await dismissCrashAlert();
  return false;
}

// ───────────────────────── ввод ─────────────────────────

/** Ввод (в т.ч. иврита) значением элемента: clearValue + setValue. Клавиатуру на iOS скрыть. */
export async function typeInto(el: El, text: string) {
  await el.waitForDisplayed({ timeout: 15000 });
  await el.clearValue();
  if (text) await el.setValue(text);
  if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
}

// ───────────────────────── геометрия ─────────────────────────

export type Box = { x: number; y: number; width: number; height: number };
export async function box(el: El): Promise<Box> {
  const { x, y } = await el.getLocation();
  const { width, height } = (await el.getSize()) as { width: number; height: number };
  return { x, y, width, height };
}
export const centerX = (b: Box) => b.x + b.width / 2;
export async function screenCenterX() { return (await driver.getWindowSize()).width / 2; }

// ───────────────────────── брахот (#1c8de4) ─────────────────────────

/** Карточка брахи в списке: «<название>, נוסח …». */
export const brachaCard = (title: string) => buttonStartsWith(`${title}, נוסח`);

/** Список брахот. После #4cfbf19e (21.10) вкладки поменялись: список брахот — под одной из вкладок «תהילים»/«ברכות»
 *  (на 21.10 — под иконкой закладки). Пробуем обе, без координат. */
export async function openBrachotList(probe = 'בורא פרי העץ') {
  await goHome();
  for (const tab of ['תהילים', 'ברכות'] as const) {
    await goTab(tab);
    const card = await brachaCard(probe);
    if (await card.waitForExist({ timeout: 6000 }).then(() => true, () => false)) return;
  }
  throw new Error(`список брахот не найден (нет карточки «${probe}, נוסח…» ни под «תהילים», ни под «ברכות»)`);
}
/** Открыть браху из списка (до 8 прокруток). */
export async function openBracha(title: string) {
  await openBrachotList();
  const card = await brachaCard(title);
  for (let i = 0; i < 8 && !(await shown(card)); i++) await swipeUp();
  await card.click();
  await (await buttonStartsWith('בחירת נוסח')).waitForExist({ timeout: 20000 });
}
/** Кнопка-заголовок «בחירת נוסח. הנוסח המוצג: X» (iOS) / заголовок с «(X)» (Android). */
export async function titleButton(): Promise<El> {
  const el = driver.isAndroid
    ? await $('android=new UiSelector().descriptionStartsWith("בחירת נוסח")')
    : await buttonStartsWith('בחירת נוסח');
  await el.waitForExist({ timeout: 20000 });
  return el as unknown as El;
}

// ───────────────────────── каталог «תפילות» (#110daf) ─────────────────────────

export const EMPTY_SEARCH = 'לא נמצאו תפילות';
export const CLEAR_SEARCH = 'ניקוי החיפוש';
export const LESSONS_CARD = 'שיעורי תורה';
/** Карточка «שיעורי תורה» (кнопка «שיעורי תורה, השיעורים הזמינים לקריאה»). */
export const lessonsCard = () => buttonStartsWith(`${LESSONS_CARD}, `);

/** Названия карточек каталога, которые сейчас в дереве (по кнопкам «<название> — לחיצה…» / «שיעורי תורה, …»). */
export async function catalogTitles(): Promise<string[]> {
  const out: string[] = [];
  for (const n of await nodes()) {
    const m = n.label.match(/^(.+?) — לחיצה/) ?? (n.label.startsWith(`${LESSONS_CARD}, `) ? [n.label, LESSONS_CARD] : null);
    if (m && !out.includes(m[1])) out.push(m[1]);
  }
  return out;
}
/** «ניקוי החיפוש» — одно нажатие, клавиатуру НЕ скрываем: #8a7f1a исправлен (עבר QA 25.10), одно нажатие очищает поиск и закрывает
 *  клавиатуру. Обход «сначала скрыть клавиатуру» убран 25.10. */
export async function tapClearSearch() {
  const b = await button(CLEAR_SEARCH);
  if (await b.isExisting().catch(() => false)) await b.click();
  else await tapText(CLEAR_SEARCH);
}

// ───────────────────────── главная / «המסע שלי» ─────────────────────────

/** Название ближайшей молитвы в шапке главной (крупный текст под приветствием). */
export async function homePrayerTitle(): Promise<string | null> {
  const ns = await nodes();
  return ns.filter((n) => ['שחרית', 'מנחה', 'ערבית'].includes(n.label) && n.y < 420).sort((a, b) => a.y - b.y)[0]?.label ?? null;
}
export async function totalPrayers() { return counter('סה״כ תפילות'); }

/** Элемент виден целиком в окне (рамка внутри экрана). */
export async function fullyOnScreen(el: El): Promise<boolean> {
  if (!(await el.isExisting().catch(() => false))) return false;
  const b = await box(el);
  const { height } = await driver.getWindowSize();
  return b.y >= 0 && b.y + b.height <= height && b.height > 0;
}

