export const HISTORY_TITLE = 'היסטוריית התפילות שלי';     // док. S-26; было «היסטוריית תפילות שלי» (#9e970625)
export async function openHistoryFromHome() {
  await goHome();
  await (await scrollToText('צפה בהכל')).click();
  await (await byText(HISTORY_TITLE)).waitForExist({ timeout: 20000 });
}
/** Узел заголовка экрана (StaticText с точным текстом, верх экрана) и «חזרה» в шапке. */
export async function headerNodes(title: string) {
  const ns = await nodes();
  const t = ns.find((n) => n.label === title && n.y < 140 && /StaticText|TextView/.test(n.type));
  const back = ns.find((n) => n.label === 'חזרה' && n.y < 140);
  return { t, back };
}

