export const APPROVED_RE = '(\\d+) מתוך (\\d+) קטעים מאושרים';

/** Кнопка, имя которой содержит текст (для «+ …» / «↑ …» — символ в начале подписи). */
export function buttonContaining(part: string) {
  return driver.isAndroid
    ? $(`android=new UiSelector().descriptionContains("${q(part)}")`)
    : $(`-ios predicate string:type == "XCUIElementTypeButton" AND (name CONTAINS "${q(part)}" OR label CONTAINS "${q(part)}")`);
}
export async function countButtonsContaining(part: string): Promise<number> {
  return (await nodes()).filter((n) => /Button|View/.test(n.type) && n.label.includes(part)).length;
}
/** «N מתוך M קטעים מאושרים» → [N, M]. */
export async function approvedCount(): Promise<[number, number]> {
  const el = await byTextMatches(APPROVED_RE);
  await el.waitForExist({ timeout: 20000 });
  const t = String((await el.getAttribute(driver.isAndroid ? 'text' : 'label').catch(() => '')) || (await el.getText()));
  const m = t.match(/(\d+) מתוך (\d+)/);
  if (!m) throw new Error(`счётчик קטעים не прочитан: «${t}»`);
  return [Number(m[1]), Number(m[2])];
}
/** Список קטעים экрана молитвы в админке: подписи «N, <заголовок>, <статус>» по порядку. */
export async function sectionRows(): Promise<string[]> {
  const out: string[] = [];
  for (let pass = 0; pass < (driver.isAndroid ? 6 : 1); pass++) {
    for (const n of await nodes()) if (/^\d+, .+, .+/.test(n.label) && !out.includes(n.label)) out.push(n.label);
    if (driver.isAndroid) await swipeUp();
  }
  return out.sort((a, b) => Number(a.split(',')[0]) - Number(b.split(',')[0]));
}

