export async function saveShot(name: string) {
  const dir = path.join(QA_DIR, 'screenshots/app-regress/qa-2110');
  fs.mkdirSync(dir, { recursive: true });
  const f = path.join(dir, name);
  await driver.saveScreenshot(f);
  return f;
}
export async function expectNoText(part: string) {
  expect(await shown(byTextContains(part))).toBe(false);
}
